import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function DeliveryDashboard() {
  const [deliveries, setDeliveries] = useState<any[]>([]);
  const navigate = useNavigate();

  useEffect(() => {
    axios.get("http://localhost:5000/api/delivery").then((res) => {
      setDeliveries(res.data);
    });
  }, []);

  // ✅ DELETE handler
  const handleDelete = async (id: string) => {
    if (window.confirm("Are you sure you want to delete this delivery?")) {
      try {
        await axios.delete(`http://localhost:5000/api/delivery/${id}`);
        // remove from UI after delete
        setDeliveries((prev) => prev.filter((d) => d._id !== id));
      } catch (error) {
        alert("❌ Failed to delete delivery");
        console.error("Delete error:", error);
      }
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Delivery Dashboard</h2>
      <table>
        <thead>
          <tr>
            <th>Customer ID</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {deliveries.map((delivery) => (
            <tr key={delivery._id}>
              <td>{delivery.customerId}</td>
              <td>{delivery.status}</td>
              <td>
                <button onClick={() => navigate(`/delivery/${delivery._id}`)}>View</button>
                <button onClick={() => navigate(`/edit-delivery/${delivery._id}`)}>✏️ Edit</button>
                <button onClick={() => handleDelete(delivery._id)}>🗑 Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
